from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
left_movement = Motor(Port.B, Direction.COUNTERCLOCKWISE)
right_movement = Motor(Port.A, Direction.CLOCKWISE)
drive_base = DriveBase(left_movement, right_movement, 62.4, 205.5)
GateLeft = Motor(Port.F, Direction.COUNTERCLOCKWISE)
GateRight = Motor(Port.E, Direction.COUNTERCLOCKWISE)
Sweeper = Motor(Port.C, Direction.COUNTERCLOCKWISE)

def Gate(Direction_):
    GateLeft.dc(100 * Direction_)
    GateRight.dc((88 * Direction_) * -1)
    wait(500)

def set_up_drivebase():
    wait(1000)
    drive_base.use_gyro(True)
    drive_base.settings(straight_speed=200)
    drive_base.settings(straight_acceleration=750)
    drive_base.settings(turn_rate=350)
    drive_base.settings(turn_acceleration=200)
    Sweeper.dc(-100)
    wait(1000)

def Close_Arm():
    GateLeft.dc(-100)
    wait(200)
    GateLeft.hold()
    GateRight.dc(88)
    wait(200)
    GateRight.hold()

def my_1_Green_Orange():
    Gate(1)
    drive_base.straight(130, then=Stop.BRAKE)
    drive_base.turn(90)
    drive_base.straight(350, then=Stop.BRAKE)
    drive_base.straight(200, then=Stop.BRAKE)
    Gate(-1)
    drive_base.straight(-420, then=Stop.BRAKE)
    drive_base.turn(-45, then=Stop.BRAKE)
    drive_base.straight(-270, then=Stop.BRAKE)
    drive_base.straight(20, then=Stop.BRAKE)
    Gate(1)
    drive_base.straight(-160, then=Stop.BRAKE)
    drive_base.turn(44)
    drive_base.straight(670, then=Stop.BRAKE)
    Gate(-1)
    drive_base.settings(straight_acceleration=200)
    drive_base.straight(-390, then=Stop.BRAKE)
    drive_base.settings(straight_acceleration=750)
    drive_base.turn(25)
    drive_base.straight(-350, then=Stop.BRAKE)
    drive_base.straight(100, then=Stop.BRAKE)
    drive_base.turn(-20)
    Gate(1)
    drive_base.turn(20)
    drive_base.straight(-100, then=Stop.BRAKE)
    drive_base.turn(-28)
    drive_base.straight(-100, then=Stop.BRAKE)
    drive_base.turn(-180)

def my_2_Red_Blue():
    Gate(1)
    drive_base.turn(17)
    drive_base.straight(600, then=Stop.BRAKE)
    Gate(-1)
    drive_base.straight(-600, then=Stop.BRAKE)
    drive_base.turn(35, then=Stop.BRAKE)
    Gate(1)
    drive_base.straight(-100, then=Stop.BRAKE)
    Gate(-1)
    drive_base.turn(-50, then=Stop.BRAKE)
    drive_base.straight(300, then=Stop.BRAKE)
    Gate(1)
    drive_base.straight(400, then=Stop.BRAKE)
    Gate(-1)
    drive_base.straight(-740, then=Stop.BRAKE)
    drive_base.straight(90, then=Stop.BRAKE)
    drive_base.turn(25, then=Stop.BRAKE)
    Gate(1)
    drive_base.turn(-23, then=Stop.BRAKE)

def my_3_outside():
    drive_base.straight(-100, then=Stop.BRAKE)
    drive_base.turn(-90, then=Stop.BRAKE)
    Close_Arm()
    drive_base.straight(280, then=Stop.BRAKE)
    drive_base.turn(90, then=Stop.BRAKE)
    drive_base.straight(990, then=Stop.BRAKE)
    drive_base.turn(90, then=Stop.BRAKE)
    drive_base.straight(-200, then=Stop.BRAKE)
    drive_base.straight(890, then=Stop.BRAKE)
    drive_base.turn(90, then=Stop.BRAKE)
    drive_base.straight(-200, then=Stop.BRAKE)
    drive_base.straight(1930, then=Stop.BRAKE)
    drive_base.arc(100, angle=90)
    drive_base.straight(920, then=Stop.BRAKE)
    drive_base.turn(90, then=Stop.BRAKE)
    drive_base.straight(-200, then=Stop.BRAKE)
    drive_base.straight(1000, then=Stop.BRAKE)
    drive_base.turn(90, then=Stop.BRAKE)
    drive_base.straight(-200, then=Stop.BRAKE)
    GateLeft.dc(100)
    drive_base.straight(-50, then=Stop.BRAKE)
    drive_base.straight(475, then=Stop.BRAKE)
    Close_Arm()


# The main program starts here.
set_up_drivebase()
drive_base.use_gyro(True)
my_1_Green_Orange()
my_2_Red_Blue()
my_3_outside()
wait(20000)
